package main

import (
	"fmt"
	"sync"
	"sync/atomic"
)

func storeMax(m *atomic.Int64, candidate int64) {
	for {
		old := m.Load()                 // read the current max atomically
		if candidate <= old {           // nothing to do; someone is already >= us
			return
		}
		if m.CompareAndSwap(old, candidate) { // commit only if no one raced us
			return
		}
		// CAS failed: another goroutine changed m; loop and retry with fresh value
	}
}

func main() {
	var m atomic.Int64
	var wg sync.WaitGroup
	for _, v := range []int64{3, 9, 4, 9, 7, 2} {
		wg.Add(1)
		go func(x int64) { defer wg.Done(); storeMax(&m, x) }(v)
	}
	wg.Wait()
	fmt.Println(m.Load()) // 9
}

