package solution

import "sync/atomic"

// Counter is a lock-free hit counter safe for concurrent use.
type Counter struct {
	n atomic.Int64 // typed atomic: aligned & zero value ready to use
}

// Inc atomically increments the counter by one.
func (c *Counter) Inc() {
	c.n.Add(1) // indivisible read-modify-write; no lost updates
}

// Value atomically reads the current total.
func (c *Counter) Value() int64 {
	return c.n.Load()
}

