package solution

import (
	"sync"
	"testing"
)

func TestCounterConcurrent(t *testing.T) {
	const goroutines = 100
	const perG = 1000
	var c Counter
	var wg sync.WaitGroup
	for g := 0; g < goroutines; g++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := 0; i < perG; i++ {
				c.Inc()
			}
		}()
	}
	wg.Wait()
	if got, want := c.Value(), int64(goroutines*perG); got != want {
		t.Errorf("Value()=%d want %d", got, want)
	}
}

