package solution

import "sync/atomic"

type IDGen struct {
	last atomic.Int64 // zero value: first Next() returns 1
}

// Next returns a fresh, strictly increasing ID, safe for concurrent use.
func (g *IDGen) Next() int64 {
	return g.last.Add(1) // fetch-and-add: returns the value AFTER incrementing
}
